/* ============================================
   MASKED INPUT
   An Input whose text the mask writes; the field,
   its states and its action slot are Input's.
   Tabular figures keep the separators still as
   digits arrive, and a hidden value's dots are
   spaced so each stands for one character.
   ============================================ */

.ds-masked-input .ds-input__field {
  font-variant-numeric: tabular-nums;
}

.ds-masked-input--concealed .ds-input__field {
  letter-spacing: var(--font-overline-letter-spacing);
}

'use client';

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Input } from '../Input/Input';
import { CircularButton } from '../CircularButton/CircularButton';
import { MOTION_SENSITIVE_HIDE_MS } from '../../tokens/motion';
import {
  applyMask,
  caretFor,
  concealMasked,
  maskCapacity,
  maskIsNumeric,
  readEdit,
  type Mask,
} from './mask';
import './MaskedInput.css';

/** Props owned by MaskedInput itself; everything else falls through to the visible `<input>`. */
type MaskedInputOwnProps = {
  /** Label text above the field. */
  label?: string;
  /** The shape of the value: a pattern where `#` takes a digit, `A` a letter and `*` either (`'(###) ###-####'`), or a function from the raw characters to the shown text. `MASK_PRESETS` holds common patterns. */
  mask: Mask;
  /** The raw value, the characters without the mask's separators (`"5550100199"`) (controlled). Pair with `onValueChange`. */
  value?: string;
  /** The raw value the field starts with (uncontrolled). */
  defaultValue?: string;
  /** Called with the raw value and the shown text as the reader types. Fires alongside the native `onChange`. */
  onValueChange?: (value: string, formatted: string) => void;
  /** Hide the value as dots until it is revealed: a tax ID, a card number. Defaults `autoComplete` to `off`. */
  sensitive?: boolean;
  /** Add a show and hide button to a sensitive field. */
  revealable?: boolean;
  /** Whether a sensitive value is shown (controlled). Pair with `onRevealedChange`. */
  revealed?: boolean;
  /** Whether a sensitive value starts shown (uncontrolled). Defaults to false. */
  defaultRevealed?: boolean;
  /** Called with the new state when the reader shows or hides the value, or it hides itself. */
  onRevealedChange?: (revealed: boolean) => void;
  /** How many of the last characters of a hidden value stay readable while the field is not focused, so a reader can tell which card it is. Defaults to 0. */
  visibleTail?: number;
  /** Hide a revealed value again after this many milliseconds, or after the library's reveal timeout with `true`. Off by default. */
  autoHideAfter?: number | boolean;
  /** Accessible name of the reveal button while the value is hidden. Defaults to "Show". */
  showLabel?: string;
  /** Accessible name of the reveal button while the value is shown. Defaults to "Hide". */
  hideLabel?: string;
  /** Component size (not the native character-width `size` attribute). */
  size?: 'default' | 'compact';
  /** Helper text below the field. */
  helperText?: string;
  /** The error message under the field; setting it marks the field invalid. */
  errorText?: React.ReactNode;
  /** Error state without a message of its own. */
  error?: boolean;
  /** The form field name. The form receives the raw value through a hidden input, never the shown text. */
  name?: string;
  /** Additional CSS classes, applied to the wrapper. */
  className?: string;
};

export interface MaskedInputProps
  extends MaskedInputOwnProps,
    Omit<React.ComponentPropsWithRef<'input'>, keyof MaskedInputOwnProps | 'type' | 'prefix'> {}

/**
 * A field that writes its value into a shape as the reader types: a phone
 * number, a card number, an ID number, a licence key. The value is the raw
 * characters; the separators are the field's, the caret holds its place
 * across them, and a paste is cleaned up. A sensitive value hides as dots
 * until the reader shows it.
 */
export function MaskedInput({
  label,
  mask,
  value: valueProp,
  defaultValue = '',
  onValueChange,
  sensitive = false,
  revealable = false,
  revealed: revealedProp,
  defaultRevealed = false,
  onRevealedChange,
  visibleTail = 0,
  autoHideAfter = false,
  showLabel = 'Show',
  hideLabel = 'Hide',
  size = 'default',
  helperText,
  errorText,
  error,
  name,
  disabled,
  className = '',
  onChange,
  onFocus,
  onBlur,
  ref,
  ...rest
}: MaskedInputProps) {
  const controlled = valueProp !== undefined;
  const [uncontrolled, setUncontrolled] = useState(() => applyMask(defaultValue, mask).raw);
  const raw = controlled ? applyMask(valueProp, mask).raw : uncontrolled;
  const masked = useMemo(() => applyMask(raw, mask), [raw, mask]);

  const revealControlled = revealedProp !== undefined;
  const [uncontrolledRevealed, setUncontrolledRevealed] = useState(defaultRevealed);
  const revealed = !sensitive || (revealControlled ? revealedProp : uncontrolledRevealed);
  const setRevealed = (next: boolean) => {
    if (!revealControlled) setUncontrolledRevealed(next);
    onRevealedChange?.(next);
  };

  const [focused, setFocused] = useState(false);
  const shown = revealed ? masked.text : concealMasked(masked, focused ? 0 : visibleTail);

  const inputRef = useRef<HTMLInputElement | null>(null);
  const setRef = (node: HTMLInputElement | null) => {
    inputRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };
  const pendingCaret = useRef<number | null>(null);
  const lastInputType = useRef<string | undefined>(undefined);

  // Put the caret back where the reader was typing once the new text is in.
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (pendingCaret.current == null || !input || document.activeElement !== input) return;
    input.setSelectionRange(pendingCaret.current, pendingCaret.current);
    pendingCaret.current = null;
  });

  // A revealed value hides itself again after the timeout, when asked to.
  const hideAfter = autoHideAfter === true ? MOTION_SENSITIVE_HIDE_MS : autoHideAfter || 0;
  const revealedNow = sensitive && revealed;
  useEffect(() => {
    if (!revealedNow || hideAfter <= 0) return;
    const timer = window.setTimeout(() => setRevealed(false), hideAfter);
    return () => window.clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- restart only when the reveal or the timeout changes
  }, [revealedNow, hideAfter]);

  const handleBeforeInput = (event: React.FormEvent<HTMLInputElement>) => {
    lastInputType.current = (event.nativeEvent as InputEvent).inputType;
  };

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const inputType = (event.nativeEvent as InputEvent).inputType ?? lastInputType.current;
    const edit = readEdit({ ...masked, text: shown }, event.target.value, inputType);
    const capped = [...edit.raw].slice(0, maskCapacity(mask)).join('');
    const next = applyMask(capped, mask);
    pendingCaret.current = caretFor(next, Math.min(edit.caretRaw, next.slots.filter(Boolean).length));
    onChange?.(event);
    if (next.raw === raw) {
      // Nothing the mask keeps changed (a refused character): restore the
      // caret, since React will not re-render on its own.
      const input = event.target;
      const caret = pendingCaret.current;
      requestAnimationFrame(() => input.setSelectionRange(caret, caret));
      return;
    }
    if (!controlled) setUncontrolled(next.raw);
    onValueChange?.(next.raw, next.text);
  };

  const revealButton =
    sensitive && revealable ? (
      <CircularButton
        icon={revealed ? 'visibility_off' : 'visibility'}
        variant="tertiary"
        size="compact"
        ariaLabel={revealed ? hideLabel : showLabel}
        aria-pressed={revealed}
        disabled={disabled}
        onClick={() => setRevealed(!revealed)}
      />
    ) : undefined;

  return (
    <>
      <Input
        autoComplete={sensitive ? 'off' : undefined}
        spellCheck={false}
        {...rest}
        // The visible field takes its id from `name`, as Input does, so an
        // ErrorSummary link built from the field name (fieldErrorsFrom) lands on it.
        id={rest.id ?? name}
        ref={setRef}
        className={['ds-masked-input', sensitive && !revealed && 'ds-masked-input--concealed', className]
          .filter(Boolean)
          .join(' ')}
        label={label}
        size={size}
        type="text"
        inputMode={rest.inputMode ?? (maskIsNumeric(mask) ? 'numeric' : undefined)}
        value={shown}
        disabled={disabled}
        error={error}
        helperText={helperText}
        errorText={errorText}
        action={revealButton}
        onBeforeInput={handleBeforeInput}
        onChange={handleChange}
        onFocus={(event) => {
          setFocused(true);
          onFocus?.(event);
        }}
        onBlur={(event) => {
          setFocused(false);
          onBlur?.(event);
        }}
      />
      {name && <input type="hidden" name={name} value={raw} disabled={disabled} />}
    </>
  );
}

// The presets are data beside the component, not a component, so the Fast
// Refresh rule that wants a component module to export only components does
// not apply to them.
// eslint-disable-next-line react-refresh/only-export-components
export { MASK_PRESETS, applyMask } from './mask';
export type { Mask, Masked } from './mask';

/**
 * The mask engine behind MaskedInput: a pattern or a function turns the raw
 * characters a person typed into the text the field shows, and a typed edit
 * of the shown text back into raw characters. No React, so a server can
 * format a stored value the same way.
 *
 * A pattern is a string where `#` takes a digit, `A` a letter, `*` either,
 * and every other character is written as it stands: `(###) ###-####`.
 * Letters keep the case they were typed in; a function mask can change it.
 */

/** A pattern string, or a function from the raw characters to the shown text. */
export type Mask = string | ((raw: string) => string);

/** Ready-made patterns. They are data, not a claim about any locale: pick the one that matches what you collect. */
export const MASK_PRESETS = {
  /** A ten-digit phone number in the US shape: `(555) 010-0199`. */
  phoneUs: '(###) ###-####',
  /** A sixteen-digit card number in four groups: `4242 4242 4242 4242`. */
  card: '#### #### #### ####',
  /** A nine-digit ID number in three groups: `123-45-6789`. */
  idNumber: '###-##-####',
  /** A five-digit postal code with an optional four-digit extension: `94107-1234`. */
  postalCode: '#####-####',
  /** A licence key of four blocks of four letters or digits: `AB12-CD34-EF56-GH78`. */
  licenceKey: '****-****-****-****',
} as const;

const TOKENS: Record<string, RegExp> = { '#': /\p{Nd}/u, A: /\p{L}/u, '*': /[\p{L}\p{Nd}]/u };
const RAW_CHAR = /[\p{L}\p{Nd}]/u;

/** The shown text, and which of its characters stand for a raw character (the rest are the mask's literals). */
export type Masked = { text: string; raw: string; slots: boolean[] };

/** How many raw characters a pattern holds, or Infinity for a function mask. */
export function maskCapacity(mask: Mask): number {
  return typeof mask === 'string' ? [...mask].filter((c) => c in TOKENS).length : Infinity;
}

/** Whether every slot in a pattern takes a digit, so the field can ask for the numeric keyboard. */
export function maskIsNumeric(mask: Mask): boolean {
  return typeof mask === 'string' && [...mask].every((c) => c === '#' || !(c in TOKENS));
}

/**
 * Raw characters through the mask. A character that fits no slot is
 * dropped; literals are written only up to the last filled slot, so a
 * half-typed number never ends in a dangling separator.
 */
export function applyMask(raw: string, mask: Mask): Masked {
  const chars = [...raw].filter((c) => RAW_CHAR.test(c));
  if (typeof mask === 'function') {
    const text = mask(chars.join(''));
    const slots = [...text].map((c) => RAW_CHAR.test(c));
    return { text, raw: [...text].filter((c) => RAW_CHAR.test(c)).join(''), slots };
  }
  let text = '';
  let pending = '';
  const slots: boolean[] = [];
  const pendingSlots: boolean[] = [];
  const kept: string[] = [];
  let i = 0;
  for (const m of mask) {
    if (i >= chars.length) break;
    const token = TOKENS[m];
    if (!token) {
      pending += m;
      pendingSlots.push(false);
      continue;
    }
    while (i < chars.length && !token.test(chars[i])) i++;
    if (i >= chars.length) break;
    text += pending + chars[i];
    slots.push(...pendingSlots, true);
    pending = '';
    pendingSlots.length = 0;
    kept.push(chars[i]);
    i++;
  }
  return { text, raw: kept.join(''), slots };
}

/** What an edit of the shown text did to the raw value, and where the caret goes. */
export type MaskEdit = { raw: string; caretRaw: number };

/**
 * Read an edit of the shown text back into raw characters. The two texts
 * are compared from each end; whatever the person removed is taken out of
 * the raw value by slot, whatever they typed or pasted goes in, and
 * removing only a separator (Backspace just after a dash) removes the raw
 * character before it, which is what the person meant.
 */
export function readEdit(previous: Masked, nextText: string, inputType?: string): MaskEdit {
  const before = [...previous.text];
  const after = [...nextText];
  let start = 0;
  while (start < before.length && start < after.length && before[start] === after[start]) start++;
  let endBefore = before.length;
  let endAfter = after.length;
  while (endBefore > start && endAfter > start && before[endBefore - 1] === after[endAfter - 1]) {
    endBefore--;
    endAfter--;
  }
  const rawIndex = (displayIndex: number) => previous.slots.slice(0, displayIndex).filter(Boolean).length;
  let rawStart = rawIndex(start);
  const rawEnd = rawIndex(endBefore);
  const inserted = after
    .slice(start, endAfter)
    .filter((c) => RAW_CHAR.test(c))
    .join('');
  const rawChars = [...previous.raw];
  if (inserted === '' && rawStart === rawEnd && endBefore > start) {
    // Only literals went: take the raw character on the side the key deletes towards.
    if (inputType === 'deleteContentForward') rawChars.splice(rawStart, 1);
    else if (rawStart > 0) {
      rawChars.splice(rawStart - 1, 1);
      rawStart -= 1;
    }
    return { raw: rawChars.join(''), caretRaw: rawStart };
  }
  rawChars.splice(rawStart, rawEnd - rawStart, ...inserted);
  return { raw: rawChars.join(''), caretRaw: rawStart + [...inserted].length };
}

/** The position in the shown text just after `count` raw characters. */
export function caretFor(masked: Masked, count: number): number {
  if (count <= 0) return 0;
  let seen = 0;
  for (let i = 0; i < masked.slots.length; i++) {
    if (masked.slots[i]) seen++;
    if (seen === count) return i + 1;
  }
  return masked.text.length;
}

/** The shown text with its raw characters hidden as dots, all but the last `visibleTail`. */
export function concealMasked(masked: Masked, visibleTail = 0, dot = '•'): string {
  const total = masked.slots.filter(Boolean).length;
  let seen = 0;
  return [...masked.text]
    .map((c, i) => {
      if (!masked.slots[i]) return c;
      seen++;
      return seen > total - visibleTail ? c : dot;
    })
    .join('');
}
